import React from "react";
import { AppContext } from "../../context/AppContext";
import { useContext, useState, useEffect} from "react";
import { fetchBudget, updateBudget } from "../../utils/budget-utils";

const Budget = () => {
  // const { budget } = useContext(AppContext);
  const context = useContext(AppContext);

    // Fetch expenses on component mount
    useEffect(() => {
      loadBudget();
    }, []);

    const loadBudget = async () => {
      try {
        const budget = await fetchBudget();
        context.setBudget(budget);
      } catch (err: any) {
        console.log(err.message);
      }
    };

    const[inputBudget, setInputBudget] = useState(context.budget.toString())
    const handleBudgetUpdate = (newBudget: string) =>{
      setInputBudget(newBudget)
    }
    const onSubmit = (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      updateBudget(parseInt(inputBudget))
    };  

    return (
    <div className="alert alert-secondary p-3 d-flex align-items-center justify-content-between">
      <div>Budget: ${context.budget}</div>
      <form onSubmit={onSubmit} className="d-flex align-items-center">
        <input
          required
          className="form-control"
          type="number"
          id="budget"
          value={inputBudget}
          onChange={(e) => handleBudgetUpdate(e.target.value)}
        />
        <button type="submit" className="btn btn-primary">
          Save
        </button>
      </form>
    </div>
  );
};

export default Budget;
